"""Host SQLite checks against the schema actually generated by Room KSP."""
from pathlib import Path
import json,sqlite3
root=Path(__file__).resolve().parents[1]
schema=json.loads((root/'app/schemas/bg.newlook.data.WorkspaceDb/2.json').read_text())['database']
def create(db,legacy=False):
 db.execute('PRAGMA foreign_keys=ON')
 for e in schema['entities']:
  sql=e['createSql'].replace('${TABLE_NAME}',e['tableName'])
  if legacy:sql=sql.replace(', `demo` INTEGER NOT NULL','').replace(", `excludedKeys` TEXT NOT NULL DEFAULT ''",'')
  db.execute(sql)
  for idx in e.get('indices',[]):db.execute(idx['createSql'].replace('${TABLE_NAME}',e['tableName']))
def project(db):db.execute("INSERT INTO projects (id,title,description,color,archived,demo) VALUES ('p','Project','Existing data',0,0,0)")
def task(db,id='t',series=None,occurrence=None):db.execute('INSERT INTO tasks (id,title,description,projectId,status,priority,tags,subtasks,seriesId,occurrenceKey,createdAt,demo) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',(id,'Task','','p','todo',1,'','[]',series,occurrence,1,0))
db=sqlite3.connect(':memory:');create(db);project(db);task(db);db.execute("DELETE FROM projects WHERE id='p'");assert db.execute('SELECT projectId FROM tasks').fetchone()==(None,);print('PASS foreign key SET NULL retains task')
project(db);task(db,'a','series','2026-10-26')
try:task(db,'b','series','2026-10-26');raise AssertionError('Duplicate occurrence accepted')
except sqlite3.IntegrityError:print('PASS unique series + occurrence constraint')
legacy=sqlite3.connect(':memory:');create(legacy,True);legacy.execute("INSERT INTO projects (id,title,description,color,archived) VALUES ('old','Keep me','Existing data',0,0)")
for table in ['tasks','projects','events','notes']:legacy.execute(f'ALTER TABLE {table} ADD COLUMN demo INTEGER NOT NULL DEFAULT 0')
legacy.execute("ALTER TABLE series ADD COLUMN excludedKeys TEXT NOT NULL DEFAULT ''")
assert legacy.execute('SELECT id,title,demo FROM projects').fetchone()==('old','Keep me',0)
for e in schema['entities']:
 a=legacy.execute('PRAGMA table_info('+e['tableName']+')').fetchall();b=db.execute('PRAGMA table_info('+e['tableName']+')').fetchall()
 assert {(r[1],r[2],r[3],r[5]) for r in a}=={(r[1],r[2],r[3],r[5]) for r in b}
print('PASS migration SQL preserves existing row and resulting columns')
db.commit();before=db.execute('SELECT count(*) FROM tasks').fetchone()
try:
 with db:db.execute("UPDATE tasks SET title='Changed'");db.execute("INSERT INTO projects (id,title) VALUES ('invalid','Invalid')")
except sqlite3.IntegrityError:pass
assert not db.execute("SELECT id FROM tasks WHERE title='Changed'").fetchall()
assert db.execute('SELECT count(*) FROM tasks').fetchone()==before
print('PASS transaction rollback does not retain partial updates')
